import{d as p,C as a,o as d,c as g,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十一章","description":"《正易心法》第三十一章——一岁之数三百六十，八卦八变气数已尽：乾宫八变复乾则天气尽，坤宫复坤则地气尽，八宫各八变，八八六十四数，天地雷风水火山泽之气无余蕴。","frontmatter":{"title":"正易心法·第三十一章","description":"《正易心法》第三十一章——一岁之数三百六十，八卦八变气数已尽：乾宫八变复乾则天气尽，坤宫复坤则地气尽，八宫各八变，八八六十四数，天地雷风水火山泽之气无余蕴。","category":"guide","aliases":["正易心法第三十一章","八卦八变气数已尽","八宫八变"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-31.md","filePath":"yijing/zheng-yi-xin-fa/chapter-31.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-31.md"},k=p({...c,setup(u){const i=[{id:"z31-01",label:"一、一岁之数",showLabel:!0,sentences:[["一岁之数，三百六十。八卦八变，",{text:"气数已尽",glossary:"qishuYijin"},"。"]],note:["一年的天数是三百六十。八卦各经八次变化，气数便完整走完。（**「尽」不是消亡，是循环完备**：从本卦出发，经七个变卦，第八变回到本卦——**一次完整的「出发→游历→归来」。**）"]},{id:"z31-02",label:"二、乾宫天气尽",showLabel:!0,sentences:[["乾、姤、遁、否、观、剥、晋、大有，八变而复乾，则天之气尽。"]],note:["乾、姤、遁、否、观、剥、晋、大有，经八变而回复为乾，则天的气数走完。（**乾宫八变正是第十九章所说的一卦八变**，两处完全一致。其中「晋」为游魂、「大有」为归魂——**魂离本宫再归本宫**，这才是八变的完整含义。）"]},{id:"z31-03",label:"三、坤宫地气尽",showLabel:!0,sentences:[["坤、复、临、泰、大壮、夬、需、比，八变而复坤，则地之气尽。"]],note:["（**坤宫前五卦正是十二消息卦的「阳长」序列**：复（一阳生）→ 临（二阳）→ 泰（三阳）→ 大壮（四阳）→ 夬（五阳）——从纯阴出发，逐爻变阳。后两卦「需」「比」则是游魂与归魂，与乾宫同例。**乾宫从纯阳往阴走，坤宫从纯阴往阳走——两宫正好是一对镜像。**）"]},{id:"z31-04",label:"四、震宫雷气尽",showLabel:!0,sentences:[["震、豫、解、恒、升、井、大过、随，八变而复震，则雷之气尽。"]],note:["（**震宫第七卦是大过**——大过是第十六章八个「对体卦」（翻转不变）之一，在此正是**游魂**之位。**这不是巧合：对体卦不随翻转而变，它们在变化序列里恰好落在「魂将离本宫」的那一位上。**）"]},{id:"z31-05",label:"五、艮宫山气尽",showLabel:!0,sentences:[["艮、贲、大畜、损、睽、履、中孚、渐，八变而复艮，则山之气尽。"]],note:["（**艮宫第七卦是中孚**，同为对体卦、同为游魂位；而中孚与震宫的大过互为错卦——**两卦分居两宫的同一位置，左右相对。**）"]},{id:"z31-06",label:"六、离宫火气尽",showLabel:!0,sentences:[["离、旅、鼎、未济、蒙、涣、讼、同人，八变而复离，则火之气尽。"]],note:["（**离宫有两卦值得留意**：第四卦「未济」是六十四卦的末卦，「事未完成」；末卦「同人」与乾宫的大有同属第十八章的「舜禹之卦」（文德嗣位），**分居离、乾两宫。**）"]},{id:"z31-07",label:"七、坎宫水气尽",showLabel:!0,sentences:[["坎、节、屯、既济、革、丰、明夷、师，八变而复坎，则水之气尽。"]],note:["坎、节、屯、既济、革、丰、明夷、师，经八变而回复为坎，则水的气数走完。（**此为底本所阙**：今见底本坎宫一行丢失，此据第三十九章「八宫卦法」（坎宫：坎、节、屯、既济、革、丰、明夷、师）补足，**以成八八六十四之数**。）"]},{id:"z31-08",label:"八、巽宫风气尽",showLabel:!0,sentences:[["巽、小畜、家人、益、无妄、噬嗑、颐、蛊，八变而复巽，则风之气尽。"]],note:["（**巽宫第七卦是颐**——八个对体卦之一，也是游魂位。**颐（形如口，实两端、虚中间）与兑宫的小过（形如飞鸟）遥相映照**，正应第十八章「一在未生（中孚）、一在已过（小过）」之辨。）"]},{id:"z31-09",label:"九、兑宫泽气尽",showLabel:!0,sentences:[["兑、困、萃、咸、蹇、谦、小过、归妹，八变而复兑，则泽之气尽。"]],note:["（**兑宫第七卦是小过**——八个对体卦的最后一个。**至此可见一个规律：八个对体卦中，乾、坤、坎、离是四宫的首卦（纯卦），而颐、大过、中孚、小过分别是巽、震、艮、兑四宫的游魂卦——八个对体卦，恰好布满八宫的「首」与「游魂」两个位置。**）"]},{id:"z31-10",label:"十、无余蕴",showLabel:!0,sentences:[["凡此八卦，各八变，八八六十四数，则天、地、雷、风、水、火、山、泽之气无",{text:"余蕴",glossary:"yuyun"},"矣。",{text:"是为一义",glossary:"shiweiYiyi"},"。"]],note:["凡此八卦，各经八变，八八共六十四数，则天、地、雷、风、水、火、山、泽的气，没有剩余、没有遗漏，全部走完。这是一层意思。（**「无余蕴」＝六十四卦覆盖了八类气的所有状态**；而「**是为一义**」四个字很重要——**它暗示这个结构还有其他层面的意思未展开。** 麻衣有一个持续的写作习惯：**点出有更深的东西，但不全部展开。**）"]}],o=[{id:"qishuYijin",term:"气数已尽",pinyin:"qì shù yǐ jìn",meaning:"这一类气的数量完整走完。尽＝完整、穷尽，不是消亡，是循环完备。"},{id:"yuyun",term:"余蕴",pinyin:"yú yùn",meaning:"剩余、积存、遗漏。无余蕴即八类气全部走完，无一遗漏。"},{id:"shiweiYiyi",term:"是为一义",pinyin:"shì wéi yī yì",meaning:"这是一层意思。暗示还有其他层意思未展开——麻衣「点到为止」的写法。"}];return(b,n)=>{const l=a("DaoTextReading"),r=a("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十一章" tabindex="-1">正易心法·第三十一章 <a class="header-anchor" href="#正易心法·第三十一章" aria-label="Permalink to &quot;正易心法·第三十一章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章给出<strong>八宫八变</strong>的完整体系：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>八宫 × 每宫八卦 = 64 卦</span></span>
<span class="line"><span>每宫的循环：本卦（1）+ 七变（7）= 八卦，第八步回到本卦</span></span>
<span class="line"><span></span></span>
<span class="line"><span>乾宫：乾 → 姤 → 遁 → 否 → 观 → 剥 → 晋 → 大有 → 复乾（天气尽）</span></span>
<span class="line"><span>坤宫：坤 → 复 → 临 → 泰 → 大壮 → 夬 → 需 → 比 → 复坤（地气尽）</span></span>
<span class="line"><span>震宫：震 → 豫 → 解 → 恒 → 升 → 井 → 大过 → 随 → 复震（雷气尽）</span></span>
<span class="line"><span>艮宫：艮 → 贲 → 大畜 → 损 → 睽 → 履 → 中孚 → 渐 → 复艮（山气尽）</span></span>
<span class="line"><span>离宫：离 → 旅 → 鼎 → 未济 → 蒙 → 涣 → 讼 → 同人 → 复离（火气尽）</span></span>
<span class="line"><span>坎宫：坎 → 节 → 屯 → 既济 → 革 → 丰 → 明夷 → 师 → 复坎（水气尽）</span></span>
<span class="line"><span>巽宫：巽 → 小畜 → 家人 → 益 → 无妄 → 噬嗑 → 颐 → 蛊 → 复巽（风气尽）</span></span>
<span class="line"><span>兑宫：兑 → 困 → 萃 → 咸 → 蹇 → 谦 → 小过 → 归妹 → 复兑（泽气尽）</span></span></code></pre></div><p><strong>结论</strong>：<strong>八八六十四数，则天、地、雷、风、水、火、山、泽之气无余蕴矣。是为一义。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「气数已尽」的含义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「尽」不是消亡，是循环完备</span></span>
<span class="line"><span>  乾宫八变，第八变回到乾 = 天气走完了一个完整的周期</span></span>
<span class="line"><span>  = 从乾出发，经历七种变化形态，最终回到乾</span></span>
<span class="line"><span>  = 天气的一次完整呼吸</span></span>
<span class="line"><span></span></span>
<span class="line"><span>类比：一年四季 春→夏→秋→冬→春</span></span>
<span class="line"><span>     = 四季之气「尽」，但不是消亡，而是完成一个循环</span></span></code></pre></div><p><strong>八宫配八气与八节</strong>：</p><table tabindex="0"><thead><tr><th>宫</th><th>气</th><th>约当节气</th></tr></thead><tbody><tr><td>乾</td><td>天（纯阳）</td><td>夏至前后</td></tr><tr><td>坤</td><td>地（纯阴）</td><td>冬至前后</td></tr><tr><td>震</td><td>雷</td><td>春分</td></tr><tr><td>艮</td><td>山</td><td>立春</td></tr><tr><td>离</td><td>火</td><td>夏</td></tr><tr><td>坎</td><td>水</td><td>冬</td></tr><tr><td>巽</td><td>风</td><td>立夏</td></tr><tr><td>兑</td><td>泽</td><td>秋分</td></tr></tbody></table><p><strong>数字结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一年 360 天 ÷ 64 卦 ≈ 5.625 天/卦</span></span>
<span class="line"><span>一年 360 天 ÷ 8 宫 = 45 天/宫（约一个节气的长度）</span></span></code></pre></div><p><strong>与第十九章的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十九章：一卦自有八变（举乾宫为例）</span></span>
<span class="line"><span>第三十一章：八卦各八变（八宫全部列出）</span></span>
<span class="line"><span>= 第十九章是举例，本章是完整体系</span></span></code></pre></div><p><strong>「是为一义」的分量</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>麻衣没有说「此章毕」，而说「这是一层意思」</span></span>
<span class="line"><span>= 暗示这个八宫八变的结构，还有其他层面的意思未展开</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把八宫各自念一遍，<strong>注意每宫都是「本卦→七变→归本卦」</strong>；</li><li>再注意乾宫的「晋」（游魂）与「大有」（归魂）——<strong>它与十二消息卦的顺序不同</strong>；</li><li>最后读「是为一义」——<strong>这是麻衣的留白。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>一岁之数</strong>：三百六十。</li><li><strong>八卦八变</strong>：每宫八变而复本卦。</li><li><strong>气数已尽</strong>：不是消亡，是循环完备。</li><li><strong>八宫配八气</strong>：天地雷风、水火、山泽。</li><li><strong>无余蕴</strong>：六十四卦覆盖八类气的所有状态。</li><li><strong>是为一义</strong>：还有其他层面未展开。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(l,{colophon:"一岁三百六十 · 八宫八变 · 气数已尽 · 无余蕴",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十一章原文",sections:i,glossary:o}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入，唯底本乾宫阙「否」、且整阙坎宫一行，此据第十九章「一卦八变」与第三十九章「八宫卦法」补足（乾宫作「乾、姤、遁、否、观、剥、晋、大有」，坎宫作「坎、节、屯、既济、革、丰、明夷、师」），以成「八八六十四」之数。此系脱文，非麻衣之误。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"八变",pinyin:["bā","biàn"],meaning:"从本卦出发，经七个变卦，第八变复归本卦——一次完整的「出发→游历→归来」。"},{term:"气数已尽",pinyin:["qì","shù"],meaning:"这一类气的数量完整走完。尽＝完整、穷尽，不是消亡，是循环完备。"},{term:"无余蕴",pinyin:["wú","yú"],meaning:"没有剩余、没有遗漏。六十四卦覆盖八类气（天地雷风、水火、山泽）的所有状态。"},{term:"是为一义",pinyin:["shì","wéi"],meaning:"这是一层意思——暗示还有其他层意思未展开，是麻衣典型的「点到为止」。"},{term:"游魂与归魂",pinyin:["yóu","hún"],meaning:"七变中的第六变（上爻变）为游魂、第七变（四爻复变）为归魂。乾宫的晋与大有即此二卦。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章给出<strong>八宫八变</strong>的完整体系：<strong>八宫 × 每宫八卦 = 64 卦</strong>，每宫「本卦 → 七变 → 复本卦」，八类气各自完整循环一次，<strong>无余蕴</strong>。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「气数已尽」的含义</strong>：<strong>「尽」不是消亡，是循环完备。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾宫八变，第八变回到乾 = 天气走完一个完整周期</span></span>
<span class="line"><span>= 天气的一次完整呼吸</span></span>
<span class="line"><span>类比：一年四季 春夏秋冬春 = 四季之气「尽」，是完成循环，不是消亡</span></span></code></pre></div><p><strong>为什么是「八变」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六爻卦有六个爻位，但从本宫出发的变化规律是：</span></span>
<span class="line"><span>初→二→三→四→五→上（游魂）→四（归魂）→本</span></span>
<span class="line"><span>= 恰好八步</span></span>
<span class="line"><span>这是「出发→远游→归来」的完整结构</span></span></code></pre></div><p><strong>与第十九章的关系</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td>第十九章</td><td>一卦自有八变（举乾宫为例）</td></tr><tr><td>第三十一章</td><td>八卦各八变（八宫全部列出）</td></tr></tbody></table><p><strong>「是为一义」的分量</strong>：麻衣没有说「此章毕」，而说「<strong>这是一层意思</strong>」——<strong>暗示还有其他层未展开。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把八宫念一遍，<strong>注意每宫都是「本卦→七变→归本卦」</strong>；</li><li>注意乾宫的「晋」（游魂）「大有」（归魂）——<strong>与十二消息卦的顺序不同，是另一套逻辑</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「气无余蕴」是发现了宇宙的完整，还是验证了一个自洽的符号系统？</strong> 我的看法：<strong>麻衣没有区分这两者，而这正是他的洞见的边界，也是他的力量所在。</strong> <strong>用八类气定义宇宙，再用八卦的变化覆盖八类气——这个「无余蕴」确实带有自证性。</strong> 但要注意：<strong>「自证」不等于「无效」。</strong> 一个符号系统可以自洽，也可以同时<strong>对应真实</strong>——判据不在系统内部，而在它能否<strong>指向系统之外的东西</strong>。麻衣的「无余蕴」至少做了这件事：<strong>它把「天、地、雷、风、水、火、山、泽」八类现象，一一落到了具体的卦上。</strong> 这就是「落处」。<strong>至于宇宙是不是真的只有八类气——这个问题，麻衣没有回答，也不打算回答。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>一年的天数是三百六十。八卦各经八次变化，气数便完整走完。</p><p>乾、姤、遁、否、观、剥、晋、大有，经八变而回复为乾，则天的气数走完。坤、复、临、泰、大壮、夬、需、比，经八变而回复为坤，则地的气数走完。震、豫、解、恒、升、井、大过、随，八变而复震，则雷的气数走完。艮、贲、大畜、损、睽、履、中孚、渐，八变而复艮，则山的气数走完。离、旅、鼎、未济、蒙、涣、讼、同人，八变而复离，则火的气数走完。坎、节、屯、既济、革、丰、明夷、师，八变而复坎，则水的气数走完。巽、小畜、家人、益、无妄、噬嗑、颐、蛊，八变而复巽，则风的气数走完。兑、困、萃、咸、蹇、谦、小过、归妹，八变而复兑，则泽的气数走完。</p><p>凡此八卦，各经八变，八八共六十四数，则天、地、雷、风、水、火、山、泽的气，没有剩余、没有遗漏，全部走完。这是一层意思。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十一章把第十九章的「八变」从一例推到了全体——<strong>八卦各走一趟，六十四卦不多不少。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「气数已尽」</strong>——这个「尽」要读对：<strong>不是「完了」，是「走完了一圈」。</strong> 天气尽，是天气经历了一次完整的呼吸。</li><li><strong>八宫配八气</strong>——乾天、坤地、震雷、艮山、离火、坎水、巽风、兑泽。<strong>这不是把八卦配上八种物象，是把六十四卦切成了八条完整的生命线。</strong></li><li><strong>乾宫里的「晋」与「大有」</strong>——它们不是十二消息卦，是<strong>游魂与归魂</strong>。<strong>这说明八变的逻辑不是「气的消长」，而是「魂的游归」。</strong> 前者讲时间，后者讲归属。</li><li><strong>与第十九章的关系</strong>——第十九章举一例，本章列全体。<strong>两章合起来，就是「一卦八变」与「八宫八变」的完整体系。</strong></li><li><strong>「是为一义」</strong>——这四个字我很在意。<strong>麻衣没有说「此章毕」，他说「这是一层意思」。</strong> 这意味着：<strong>八宫八变还有别的层面没展开。</strong> 这可能就是——<strong>时间（气数）、象（八卦）、人事（游魂归魂），各是一义。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「气无余蕴」是发现了宇宙的完整，还是验证了一个自洽的符号系统？</strong> 我的看法：<strong>麻衣没有区分，而这既是他的边界，也是他的力量。</strong> 用八类气定义宇宙、再用八卦的变化覆盖八类气——<strong>这个「无余蕴」确实带有自证性。</strong> 但**「自证」不等于「无效」**：一个符号系统可以自洽，也可以同时对应真实。<strong>判据不在系统内部，而在它能否指向系统之外的东西。</strong> 麻衣做了这件事：<strong>他把八类现象一一落到了具体的卦上——这就是「落处」。</strong> 至于宇宙是不是真的只有八类气，<strong>他没有回答，也不打算回答。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-19">第十九章 · 凡具八卦</a> — 一卦自有八变（本章列全体）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-29">第二十九章 · 以闰求之</a> — 一岁之数三百六十</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-30">第三十章 · 画纯为叠</a> — 360 与 384 之别</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-39">第三十九章</a> — 归魂与复变（八宫变的规则）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 八卦的八类物象</li></ul>`,23))])}}});export{m as __pageData,k as default};
